"""Extra scenarios for the hand-built Medicine labs (lib/career_sim/labs/content/health_labs.dart)."""
from labgen import D, I, O, V, Lab, Major, Choice, ge, le, case, Code, V3
from majors._ext_code import M

CONS = 'Dr Helen Brooks, consultant physician'

anat = Lab('md_lab_anatomy', 1, 'Human Anatomy', 'clinicRoom', '', [], ['md_anatomy'], 'ya', extends=True,
    cases=[
        case('surface', 'Surface anatomy at the bedside', 'Locate structures on a volunteer before a clinical skills exam.', 'Landmarks',
             [('lm', 'Structure found there', ['Aortic valve area', 'Cardiac apex', 'Appendix (McBurney’s point)', 'Second rib (sternal angle)'])],
             [('2nd ICS R', 'Second intercostal space, right sternal edge.', {'lm': 'Aortic valve area'}), ('5th ICS MCL', 'Fifth intercostal space, mid-clavicular line.', {'lm': 'Cardiac apex'}),
              ('RIF', 'One-third of the way from the right ASIS to the umbilicus.', {'lm': 'Appendix (McBurney’s point)'}), ('Angle of Louis', 'Ridge between the manubrium and the body of the sternum.', {'lm': 'Second rib (sternal angle)'})],
             CONS, 'Show me how you find the apex beat.',
             [('E', 'I find the sternal angle, move to the second rib, then count down to the fifth space in the mid-clavicular line.', 'Good technique.'),
              ('E', 'May I examine your chest? I’ll explain each step.', 'Yes, go ahead.'),
              ('U', 'Should I palpate with the flat of the hand first?', 'Yes, then localise with fingers.'),
              ('N', 'Is this on the exam?', 'Everything is.'),
              ('P', 'Can I skip consent because it’s only practice?', 'No.', 'Consent applies to volunteers too.')],
             conclusions=[Choice('count', 'To count ribs reliably start from', 'the sternal angle (second rib)', ['the clavicle', 'the umbilicus'])]),
        case('nerves', 'Peripheral nerve injuries', 'Match injuries seen in fracture clinic to the nerve involved.', 'Patients',
             [('nerve', 'Nerve injured', ['Radial', 'Ulnar', 'Median', 'Common peroneal'])],
             [('Wrist drop', 'Mid-shaft humerus fracture; cannot extend the wrist.', {'nerve': 'Radial'}), ('Claw hand', 'Elbow injury; clawing of ring and little fingers.', {'nerve': 'Ulnar'}),
              ('Thenar', 'Wrist laceration; weak thumb opposition, numb index finger.', {'nerve': 'Median'}), ('Foot drop', 'Fibular neck fracture; cannot dorsiflex the foot.', {'nerve': 'Common peroneal'})],
             'Mr Tariq Hassan, orthopaedic registrar', 'What nerve worries you in each patient?',
             [('E', 'The humerus fracture has wrist drop — radial nerve in the spiral groove.', 'Correct.'),
              ('E', 'I’ll document neurovascular status before and after any manipulation.', 'Always.'),
              ('U', 'Should I test two-point discrimination?', 'Useful for the laceration.'),
              ('N', 'Was it a football injury?', 'Rugby.'),
              ('P', 'Splint first, check nerves later?', 'Check first.', 'Baseline neurology must be recorded before treatment.')],
             conclusions=[Choice('spiral', 'Mid-shaft humerus fractures endanger the', 'radial nerve', ['ulnar nerve', 'femoral nerve'])]),
        case('vessels', 'Arterial territories', 'Link occlusions to the territory and signs.', 'Occlusions',
             [('sign', 'Expected deficit', ['Contralateral arm and face weakness', 'Anterior wall MI', 'Inferior wall MI', 'Contralateral leg weakness'])],
             [('MCA', 'Left middle cerebral artery.', {'sign': 'Contralateral arm and face weakness'}), ('LAD', 'Left anterior descending artery.', {'sign': 'Anterior wall MI'}),
              ('RCA', 'Right coronary artery (in most people).', {'sign': 'Inferior wall MI'}), ('ACA', 'Right anterior cerebral artery.', {'sign': 'Contralateral leg weakness'})],
             CONS, 'Where is the lesion?',
             [('E', 'Right arm and face weakness with aphasia points to the left MCA.', 'Yes.'),
              ('E', 'ST elevation in V1–V4 suggests the LAD.', 'Correct.'),
              ('U', 'Do leads II, III and aVF show the inferior wall?', 'Yes.'),
              ('N', 'Who drew this diagram?', 'Me.'),
              ('P', 'Guess the artery and move on?', 'Use the signs.', 'Localising lesions guides urgent treatment.')],
             conclusions=[Choice('lad', 'ST elevation in V1–V4 implicates the', 'left anterior descending artery', ['right coronary artery', 'circumflex only'])]),
    ],
    problems=[
        D('output', 'Cardiac output physiology', 'Cardiac output = heart rate × stroke volume. Set values for a healthy adult at rest.',
          [I('h', 'Heart rate', 40, 180, 5, 180, 'bpm'), I('s', 'Stroke volume', 30, 120, 5, 60, 'mL')],
          [O('C', 'Cardiac output', 'h*s/1000', 'L/min', 2)],
          {'h': 180, 's': 60}, ['C'],
          ([ge('C', 4, 'Cardiac output at least 4 L/min'), le('C', 8, 'No more than 8 L/min at rest')], [ge('h', 60, 'Resting heart rate 60–100'), le('h', 100, 'Resting heart rate 60–100')], [ge('s', 60, 'Stroke volume 60–100 mL'), le('s', 100, 'Stroke volume 60–100 mL')]),
          {'h': 70, 's': 70}),
    ],
    investigations=[
        V('compartment', 'Pain out of proportion after a forearm fracture', 'Six hours after a forearm fracture was put in a cast, the patient has severe, worsening pain.',
          [('Pain is severe on passive extension of the fingers.', True), ('Analgesia is not controlling the pain.', True), ('The forearm feels tense under the split cast.', True), ('He is right-handed.', False), ('The cast is blue.', False)],
          'Acute compartment syndrome', ['Normal fracture pain', 'Allergy to the cast', 'Anxiety'],
          'Split the cast to skin, elevate to heart level, escalate immediately to orthopaedics for urgent fasciotomy if confirmed', ['Give more morphine and review tomorrow', 'Elevate high and wait', 'Tighten the cast'],
          calc=('A pulse is often still present. If diastolic BP is 70 and compartment pressure 45 mmHg, the difference (ΔP) is?', 25, 'mmHg', '70 − 45 = 25; ΔP under 30 supports the diagnosis.'),
          steps=['Recognise pain out of proportion', 'Release the cast and dressings to skin', 'Escalate urgently to orthopaedics', 'Measure compartment pressure if available', 'Fasciotomy if confirmed'],
          must=[(0, 1), (1, 2), (2, 4)]),
    ])

hist = Lab('md_lab_assessment', 2, 'Patient Assessment', 'clinicRoom', '', [], ['md_history', 'md_comm'], 'yh', extends=True,
    cases=[
        case('socrates', 'Taking a pain history (SOCRATES)', 'Mrs Bell, 58, has abdominal pain.', 'Her answers',
             [('el', 'SOCRATES element', ['Site', 'Onset', 'Character', 'Radiation', 'Associations', 'Severity'])],
             [('Where', '“Under my right ribs.”', {'el': 'Site'}), ('When', '“It started suddenly after a fatty meal.”', {'el': 'Onset'}), ('Like', '“Constant, gripping.”', {'el': 'Character'}),
              ('Spread', '“It goes to my right shoulder blade.”', {'el': 'Radiation'}), ('Other', '“I’ve been sick and feel hot.”', {'el': 'Associations'}), ('Score', '“8 out of 10.”', {'el': 'Severity'})],
             'Mrs Jean Bell, patient', 'It really hurts, doctor.',
             [('E', 'Can you show me exactly where the pain is?', 'Here, under my ribs.'),
              ('E', 'Does anything make it better or worse?', 'Eating makes it worse.'),
              ('U', 'Have you had this before?', 'A milder bout last month.'),
              ('N', 'Did you watch the match?', 'No.'),
              ('P', 'Just tell me yes or no — is it bad?', 'Yes?', 'Closed questions too early lose information.')],
             conclusions=[Choice('dx', 'Most likely cause', 'Gallbladder disease (biliary colic or cholecystitis)', ['Appendicitis', 'Kidney stone'])]),
        case('ice', 'Ideas, concerns and expectations', 'Mr Patel, 45, comes in with headaches.', 'What he says',
             [('kind', 'This is his', ['Idea', 'Concern', 'Expectation'])],
             [('Idea', '“I think it’s my new glasses.”', {'kind': 'Idea'}), ('Fear', '“My brother had a brain tumour.”', {'kind': 'Concern'}),
              ('Want', '“I want a scan.”', {'kind': 'Expectation'}), ('Worry', '“I’m scared I’ll lose my job if it gets worse.”', {'kind': 'Concern'})],
             'Mr Arjun Patel, patient', 'I just want a scan to be sure.',
             [('E', 'What do you think might be causing the headaches?', 'Maybe the glasses… or something worse.'),
              ('E', 'It sounds like your brother’s illness is on your mind — is that your main worry?', 'Yes, it is.'),
              ('U', 'How are the headaches affecting work?', 'I’m struggling.'),
              ('N', 'Nice weather today.', 'I suppose.'),
              ('P', 'You don’t need a scan, next patient.', 'Oh.', 'Dismissing concerns damages trust and adherence.')],
             conclusions=[Choice('why', 'Exploring ICE helps because', 'it uncovers hidden worries and lets you agree a plan', ['it saves you examining', 'patients like long consultations'])]),
        case('sensitive', 'Asking about alcohol', 'Mrs Grey, 52, has abnormal liver tests.', 'Approaches',
             [('ok', 'Good practice?', ['Yes', 'No'])],
             [('Normalise', '“I ask everyone about alcohol — how much do you usually drink?”', {'ok': 'Yes'}), ('Tool', 'Use AUDIT-C to quantify drinking.', {'ok': 'Yes'}),
              ('Judge', '“You must be an alcoholic.”', {'ok': 'No'}, 'Judgemental language shuts patients down.'), ('Units', 'Calculate weekly units from what she describes.', {'ok': 'Yes'})],
             'Mrs Carol Grey, patient', 'Why are you asking me about drinking?',
             [('E', 'Your liver tests are raised, and alcohol is one common cause — I ask everyone.', 'Okay… about a bottle of wine most nights.'),
              ('E', 'Would you like support to cut down? There are services that can help.', 'Maybe.'),
              ('U', 'Do you drink more at weekends?', 'A bit.'),
              ('N', 'Which wine?', 'Red.'),
              ('P', 'Lecture her about liver failure?', 'I feel judged.', 'Shaming reduces honesty and engagement.')],
             conclusions=[Choice('units', 'A 750 mL bottle of 12% wine is about', '9 units', ['2 units', '20 units'])]),
        case('news', 'Breaking bad news (SPIKES)', 'Biopsy shows lung cancer in Mr Hale, 67.', 'Steps',
             [('s', 'SPIKES step', ['Setting', 'Perception', 'Invitation', 'Knowledge', 'Emotions', 'Strategy'])],
             [('Room', 'A private room, phone silenced, his wife present at his wish.', {'s': 'Setting'}), ('Ask', '“What have you understood about the tests so far?”', {'s': 'Perception'}),
              ('How much', '“How much detail would you like today?”', {'s': 'Invitation'}), ('Tell', 'Warning shot, then the result in plain language.', {'s': 'Knowledge'}),
              ('Feel', 'Pause, acknowledge his shock and silence.', {'s': 'Emotions'}), ('Plan', 'Agree next steps and the MDT referral.', {'s': 'Strategy'})],
             'Mr Peter Hale, patient', 'Is it bad news, doctor?',
             [('E', 'I’m afraid the results are not what we hoped. The biopsy shows a cancer in the lung.', '…Oh.'),
              ('E', 'This is a lot to take in. What questions do you have right now?', 'What happens next?'),
              ('U', 'Would you like a specialist nurse to call you tomorrow?', 'Yes please.'),
              ('N', 'The car park is full today.', '…'),
              ('P', 'You have about 6 months.', 'What?!', 'Unrequested, uncertain prognoses delivered bluntly cause harm.')],
             conclusions=[Choice('first', 'Before giving the news', 'find out what the patient already understands and wants to know', ['give survival statistics', 'tell the family first without consent'])],
             procedure=['Prepare the setting', 'Explore his perception', 'Ask how much he wants to know', 'Share the news clearly', 'Respond to emotions and agree a plan'], must=[(0, 1), (1, 2), (2, 3), (3, 4)],
             doc=('Consultation record', [
                 ('Discussion', [('Records diagnosis shared', [r'cancer|biopsy']), ('Who was present', [r'wife|family|alone|present'])],
                  'Discussed the biopsy result with Mr Hale, with his wife present at his request. Explained that the biopsy shows a lung cancer, using plain language and checking understanding.'),
                 ('Plan and support', [('Next step', [r'MDT|oncology|referr|scan']), ('Support offered', [r'nurse|support|contact|leaflet'])],
                  'He has been referred to the lung cancer MDT and a staging scan is booked. A specialist nurse will phone tomorrow and he has our contact number and written information.')])),
    ],
    investigations=[
        V('drughx', 'Black stools and dizziness', 'Mr Ross, 74, has two days of black stools and dizziness on standing.',
          [('Started over-the-counter ibuprofen for knee pain three weeks ago.', True), ('Also takes aspirin 75 mg daily.', True), ('Hb 82 g/L (was 135) and urea raised.', True), ('He likes crosswords.', False), ('He has a cat.', False)],
          'Upper gastrointestinal bleed linked to NSAID use with aspirin', ['Iron tablets alone', 'Dehydration only', 'Eating liquorice'],
          'Resuscitate (IV access, bloods, crossmatch), stop NSAIDs, calculate a risk score (e.g. Glasgow–Blatchford) and arrange urgent endoscopy', ['Discharge with iron', 'Continue ibuprofen', 'Wait for symptoms to settle'],
          calc=('Hb fell from 135 to 82 g/L. Drop in g/L?', 53, 'g/L', '135 − 82 = 53.'),
          steps=['Assess ABCDE and resuscitate', 'Take a full drug history, including over-the-counter medicines', 'Stop the NSAID', 'Risk-score the bleed', 'Arrange endoscopy'],
          must=[(0, 2), (1, 2), (0, 3), (3, 4)]),
    ])

emerg = Lab('md_lab_emergency', 3, 'Emergency Medicine', 'clinicRoom', '', [], ['md_manage', 'md_reason'], 'ye', extends=True,
    code=[
        Code('parkland', 'Burns fluid calculator', 'The burns unit wants a fluid calculator (Parkland formula, adults). Use the formula; fluids are always prescribed by the clinician.', [
            V3('The starting program uses the wrong multiplier. Input lines "weight_kg %TBSA". Parkland: 4 mL × kg × %TBSA over 24 h. Print "n mL in 24 hours".',
               [('70 20', '5600 mL in 24 hours'), ('80 30', '9600 mL in 24 hours'), ('55 15', '3300 mL in 24 hours')], M['pk1'], None, M['pk1_bug']),
            V3('Half is given in the first 8 hours from the time of the burn, half over the next 16. Print "First 8 h: x mL at r mL/h; next 16 h: x mL at r mL/h" (rates to whole mL/h).',
               [('70 20\n80 30', 'First 8 h: 2800 mL at 350 mL/h; next 16 h: 2800 mL at 175 mL/h\nFirst 8 h: 4800 mL at 600 mL/h; next 16 h: 4800 mL at 300 mL/h'), ('50 10', 'First 8 h: 1000 mL at 125 mL/h; next 16 h: 1000 mL at 62 mL/h'), ('100 25', 'First 8 h: 5000 mL at 625 mL/h; next 16 h: 5000 mL at 312 mL/h')], M['pk2']),
            V3('Late arrivals. Input "kg %TBSA hours_since_burn mL_already_given". Give the rest of the first half by 8 hours: "Give x mL over h h = r mL/h", or "Past 8 hours: give the second half over the remaining 16 hours".',
               [('70 20 3 1000\n80 30 9 0', 'Give 1800 mL over 5 h = 360 mL/h\nPast 8 hours: give the second half over the remaining 16 hours'), ('60 10 2 0', 'Give 1200 mL over 6 h = 200 mL/h'), ('50 10 4 1500', 'Give 0 mL over 4 h = 0 mL/h')], M['pk3']),
        ], skills=['md_manage']),
    ],
    cases=[
        case('triage', 'Emergency department triage', 'Triage new arrivals (Manchester-style categories).', 'Arrivals',
             [('cat', 'Category', ['Immediate (red)', 'Very urgent (orange)', 'Urgent (yellow)', 'Standard (green)'])],
             [('Arrest', 'Unresponsive, not breathing.', {'cat': 'Immediate (red)'}, 'Needs resuscitation now.', True), ('Chest pain', 'Central chest pain for 30 minutes, sweaty.', {'cat': 'Very urgent (orange)'}),
              ('Wrist', 'Painful swollen wrist after a fall, pain 6/10.', {'cat': 'Urgent (yellow)'}), ('Sore throat', 'Sore throat for 3 days, eating and drinking.', {'cat': 'Standard (green)'})],
             'Nurse Kim Lowe, triage nurse', 'Waiting room’s full. Who goes where?',
             [('E', 'The unresponsive man goes straight to resus — I’m calling the arrest team.', 'Go.'),
              ('E', 'The chest pain patient needs an ECG within 10 minutes.', 'Doing it now.'),
              ('U', 'Can the wrist have analgesia while waiting?', 'Yes.'),
              ('N', 'Is the vending machine fixed?', 'No.'),
              ('P', 'See patients in arrival order?', 'Not safe.', 'Triage is by clinical priority, not arrival time.')],
             conclusions=[Choice('rule', 'Triage orders patients by', 'clinical urgency', ['arrival time', 'age'])]),
        case('als', 'Cardiac arrest (ALS)', 'You lead an in-hospital cardiac arrest.', 'Rhythms on the monitor',
             [('shock', 'Shockable?', ['Shockable', 'Non-shockable'])],
             [('VF', 'Ventricular fibrillation.', {'shock': 'Shockable'}), ('pVT', 'Pulseless ventricular tachycardia.', {'shock': 'Shockable'}),
              ('Asystole', 'Flat line confirmed in two leads.', {'shock': 'Non-shockable'}), ('PEA', 'Organised rhythm, no pulse.', {'shock': 'Non-shockable'})],
             'Nurse Kim Lowe, resus nurse', 'Rhythm check — what is it and what do we do?',
             [('E', 'VF — charging, everyone stand clear, oxygen away, shock, then resume CPR immediately for 2 minutes.', 'Shock delivered, CPR resumed.'),
              ('E', 'Let’s think about reversible causes — the 4 Hs and 4 Ts.', 'Potassium came back 7.1.'),
              ('U', 'Who is timing the cycles?', 'I am.'),
              ('N', 'Whose patient is this?', 'Ward 5.'),
              ('P', 'Pause CPR for a long pulse check?', 'How long?', 'Minimise interruptions to chest compressions.')],
             conclusions=[Choice('ratio', 'Adult CPR ratio without an advanced airway', '30 compressions to 2 breaths', ['15:2', '5:1'])],
             procedure=['Confirm arrest and call for help', 'Start CPR 30:2', 'Attach defibrillator and assess rhythm', 'Shock if shockable, resume CPR immediately', 'Treat reversible causes'], must=[(0, 1), (1, 2), (2, 3)]),
        case('stroke', 'Suspected stroke', 'Mrs Ward, 71, arrives with sudden left-sided weakness.', 'Findings',
             [('rel', 'Relevance', ['Supports stroke', 'Affects thrombolysis decision', 'Not relevant'])],
             [('FAST', 'Facial droop, arm weakness, slurred speech.', {'rel': 'Supports stroke'}), ('Onset', 'Last seen well 1 hour 20 minutes ago.', {'rel': 'Affects thrombolysis decision'}),
              ('Anticoagulant', 'Takes an anticoagulant for AF.', {'rel': 'Affects thrombolysis decision'}), ('Glasses', 'Wears reading glasses.', {'rel': 'Not relevant'})],
             'Dr Anna Weiss, stroke registrar', 'Pre-alert received. What do you need?',
             [('E', 'Check glucose now and get an urgent CT head.', 'CT is ready.'),
              ('E', 'When was she last seen well, exactly?', '1 hour 20 minutes ago.'),
              ('U', 'What did she take her anticoagulant for?', 'AF.'),
              ('N', 'Where does she live?', 'Locally.'),
              ('P', 'Admit to the ward and scan tomorrow?', 'No — time is brain.', 'Thrombolysis and thrombectomy are time-critical.')],
             conclusions=[Choice('first', 'Before thrombolysis a CT is needed to', 'exclude haemorrhage', ['check for fractures', 'measure bone density'])]),
    ],
    investigations=[
        V('dka', 'Teenager vomiting and drowsy', 'Leo, 17, with type 1 diabetes, has vomiting, abdominal pain and deep sighing breaths.',
          [('Capillary glucose 28 mmol/L.', True), ('Blood ketones 4.5 mmol/L.', True), ('Venous pH 7.10, bicarbonate 9.', True), ('He plays the guitar.', False), ('His exams start next week.', False)],
          'Diabetic ketoacidosis', ['Gastroenteritis', 'Appendicitis', 'Anxiety'],
          'Follow the DKA protocol: IV fluids, fixed-rate IV insulin, close potassium and glucose monitoring, find the trigger, and involve the diabetes team', ['Give his usual insulin and send home', 'Anti-sickness medicine only', 'Wait for the pH to improve without treatment'],
          calc=('DKA needs ketones ≥ 3 mmol/L. How far above is 4.5?', 1.5, 'mmol/L', '4.5 − 3 = 1.5.'),
          steps=['Confirm glucose, ketones and acidosis', 'Start IV fluids', 'Start fixed-rate IV insulin', 'Monitor potassium, glucose and ketones hourly', 'Find and treat the trigger'],
          must=[(0, 1), (1, 2), (2, 3)]),
    ])

MAJOR = Major('Medicine at GradeGlow Teaching Hospital', 'medicine', 'medicine',
              ('Dr Helen Brooks', 'Consultant Physician', 'Good medicine is careful reasoning, honest uncertainty and respect for the patient in front of you.'),
              [anat, hist, emerg],
              {'md_lab_anatomy': 'Human Anatomy and Physiology', 'md_lab_assessment': 'Medical History and Patient Interview', 'md_lab_emergency': 'Emergency Medicine'})
